from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeInvoiceOperation
import os

def extract_receipt_data(document_bytes):
    """
    Extract merchant, tax, total, and items from a receipt using Azure Document Intelligence prebuilt invoice processor.

    Args:
        document_bytes (bytes): The raw bytes of the receipt document

    Returns:
        dict: Structured data containing merchant, tax, total, and items extracted from the receipt
    """
    # Get Azure credentials from environment variables
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("Azure Document Intelligence endpoint and key must be set in environment variables")

    # Create the client
    client = DocumentIntelligenceClient(endpoint, AzureKeyCredential(key))

    # Analyze the document using the prebuilt invoice model
    poller = client.begin_analyze_document("prebuilt-invoice", document_bytes)
    result = poller.result()

    # Extract structured data from the response
    extracted_data = {
        "merchant": None,
        "tax": None,
        "total": None,
        "items": []
    }

    # Process each document page
    for doc in result.documents:
        # Find merchant information
        for field in doc.fields:
            if field.name.lower() == "vendor":
                if field.value:
                    extracted_data["merchant"] = field.value.as_dict() if hasattr(field.value, 'as_dict') else str(field.value)

        # Find tax information
        for field in doc.fields:
            if field.name.lower() == "totaltax":
                if field.value:
                    extracted_data["tax"] = field.value.as_dict() if hasattr(field.value, 'as_dict') else str(field.value)

        # Find total amount
        for field in doc.fields:
            if field.name.lower() == "totalamount":
                if field.value:
                    extracted_data["total"] = field.value.as_dict() if hasattr(field.value, 'as_dict') else str(field.value)

        # Find line items
        for field in doc.fields:
            if field.name.lower() == "items":
                if field.value and isinstance(field.value, list):
                    for item in field.value:
                        if hasattr(item, 'as_dict'):
                            item_dict = item.as_dict()
                        else:
                            item_dict = str(item)

                        # Extract item details
                        item_data = {}
                        if isinstance(item_dict, dict):
                            for key, value in item_dict.items():
                                if key == "description" or key == "itemdescription":
                                    item_data["description"] = str(value) if not isinstance(value, dict) else value.get("text", str(value))
                                elif key == "quantity":
                                    item_data["quantity"] = str(value) if not isinstance(value, dict) else value.get("text", str(value))
                                elif key == "amount":
                                    item_data["amount"] = str(value) if not isinstance(value, dict) else value.get("text", str(value))
                        else:
                            # Fallback if item is not a dictionary
                            item_data = {"description": str(item)}

                        extracted_data["items"].append(item_data)

    return extracted_data
